function verifier(string $nom): void
{
    $messages = [
        "0d2960fef7f39715db75d9b152a3947076bd3b108b3cf94dfa9ec9491c003274" => "Vous avez retrouvé le fromager, enfermé dans une cave d'affinage ! Mais le ravisseur n'a pas agi seul : lisez son témoignage pour remonter la piste, puis appelez à nouveau verifier().",
        "673065da307f77be993e2dca4816b160b237219d6014e7bc6e7bb8712b884b95" => "Félicitations ! La grande industrielle du fromage voulait produire la recette en usine. Le fromager est libre, la recette est sauve, et Algoville vous offre un plateau de fromages.",
    ];
    $empreinte = hash('sha256', strtolower(trim($nom)));
    echo "\n[[ENQUETE:" . (isset($messages[$empreinte]) ? $empreinte : "KO") . "]]\n";
    if (isset($messages[$empreinte])) {
        echo $messages[$empreinte] . "\n";
    } else {
        echo "Ce n'est pas la bonne personne. Essayez encore !\n";
    }
}

